class Solution:
    def isPossibleToSplit(self, nums: List[int]) -> bool:
        nums1 = set()
        nums2 = set()

        for num in nums:
            if num in nums1:
                nums2.add(num)
            else:
                nums1.add(num)

        return len(nums1) == len(nums) // 2 and len(nums2) == len(nums) // 2
```

